import fs from 'fs';
import path from 'path';

const REPO = path.join(__dirname, '..', '..', '..');

type Pass = 'C1' | 'C1b' | 'C1c' | 'C2';
type OwnerClass = 'O' | 'C' | 'F' | 'A' | 'T';

function walk(dir: string, keep: (file: string) => boolean, out: string[] = []): string[] {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (entry.name === 'node_modules' || entry.name === '__tests__') continue;
      walk(full, keep, out);
    } else if (keep(full)) {
      out.push(full);
    }
  }
  return out;
}

function census(): Array<[Pass, string, string]> {
  const rel = (file: string): string => path.relative(REPO, file).split(path.sep).join('/');
  const hits: Array<[Pass, string, string]> = [];
  const scan = (pass: Pass, files: string[], pattern: RegExp): void => {
    for (const file of files) {
      for (const line of fs.readFileSync(file, 'utf8').split(/\r?\n/)) {
        if (pattern.test(line)) hits.push([pass, rel(file), line.trim()]);
      }
    }
  };
  const backendTs = walk(path.join(REPO, 'backend', 'src'), (file) => file.endsWith('.ts'));
  scan('C1', backendTs, /owner_?principal/i);
  scan('C1b', backendTs, /resource\.(owner|accountOwner)\b/);
  scan('C1c', walk(path.join(REPO, 'backend', 'src', 'migrations'), (file) => file.endsWith('.sql')), /owner_?principal/i);
  scan('C2', walk(path.join(REPO, 'frontend', 'src'), (file) => !/\.test\.tsx?$/.test(file)), /owner_?principal/i);
  return hits;
}

