const key = (row: readonly string[]): string => JSON.stringify(row.slice(0, 3));
const DISPOSITION = /^(group-aware|group-safe|fail-closed|writer-human-only|dead|deferred:(9|10|11|12|13):[0-9a-f]{8})$/;
// The fragment's own aliases (`owning_group*`) do not match the census pattern,
// so it contributes comments (T) only; the evaluator files carry the arm.
const EVALUATOR = new Set([
  'backend/src/services/AuthorizationService.ts',
  'backend/src/services/AuthorizationRepository.ts',
  'backend/src/utils/groupOwnerCondition.ts',
]);

describe('C-1 - the owner-reader register (AZ-A12 v3.1 G.1)', () => {
  const hits = census();

  it('prints the census it measured (pass totals), so a reviewer can rerun it', () => {
    const totals: Record<string, number> = {};
    for (const [pass] of hits) totals[pass] = (totals[pass] ?? 0) + 1;
    // eslint-disable-next-line no-console
    console.log(`C-1 census: ${JSON.stringify(totals)}`);
    expect(Object.keys(totals).sort()).toEqual(['C1', 'C1b', 'C1c', 'C2']);
  });

  const files = [...new Set([...hits.map(([, file]) => file), ...OWNER_READER_REGISTER.map(([, file]) => file)])].sort();
  it.each(files)('%s is registered line by line (no unregistered match, no stale entry)', (file) => {
    const measured = hits.filter(([, f]) => f === file).map(key).sort();
    const registered = OWNER_READER_REGISTER.filter(([, f]) => f === file).map(key).sort();
    expect(measured).toEqual(registered);
  });

  it('every row carries a known class and disposition; deferred rows name a later clause and card', () => {
    for (const row of OWNER_READER_REGISTER) {
      const [, file, line, ownerClass, disposition, why] = row;
      expect([file, line, ['O', 'C', 'F', 'A', 'T'].includes(ownerClass)]).toEqual([file, line, true]);
      expect([file, line, DISPOSITION.test(disposition)]).toEqual([file, line, true]);
      expect(why.length).toBeGreaterThan(0);
      if (disposition.startsWith('deferred:')) {
        expect([file, line, disposition.split(':')[2] in LATER_CARDS]).toEqual([file, line, true]);
      }
    }
  });

  it('no class-O row still needs change under this build\'s clauses (6, 7, 8)', () => {
    const open = OWNER_READER_REGISTER.filter(([, , , ownerClass, disposition]) =>
      ownerClass === 'O' && /^deferred:(6|7|8):/.test(disposition));
    expect(open).toEqual([]);
  });

  it('every group-aware row is the evaluator or its one shared fragment', () => {
    const outside = OWNER_READER_REGISTER.filter(([, file, , , disposition]) =>
      disposition === 'group-aware' && !EVALUATOR.has(file));
    expect(outside).toEqual([]);
    const aware = new Set(OWNER_READER_REGISTER.filter(([, , , , d]) => d === 'group-aware').map(([, file]) => file));
    expect([...aware].sort()).toEqual(['backend/src/services/AuthorizationRepository.ts', 'backend/src/services/AuthorizationService.ts']);
  });
});
